const input = $input.first().json;
const body = input.body || input;

const boardId = body.board_id || $env.JIRA_BOARD_ID || '8207';
const baseUrl = body.base_url || $env.JIRA_BASE_URL || 'https://lgucorp.atlassian.net';
const projectKeys = body.project_keys ||
  (() => { try { return JSON.parse($env.JIRA_PROJECT_KEYS || '["WBS"]'); } catch(e) { return ['WBS']; } })();
const commitMessages = body.commit_messages || [];

if (!boardId) throw new Error('board_id가 설정되지 않았습니다.');

return [{ json: { boardId, baseUrl, projectKeys, commitMessages } }];

const sprintData = $input.first().json;
const prevParams = $('Init Params').first().json;

const allSprints = sprintData.values || [];
// simple board type은 ?state=active 필터 미지원 → 코드에서 필터링
const sprints = allSprints.filter(s => s.state === 'active');

if (!sprints.length) {
  throw new Error('활성 Sprint가 없습니다. Board ID: ' + prevParams.boardId);
}

const sprint = sprints[0];
return [{ json: {
  boardId: prevParams.boardId,
  baseUrl: prevParams.baseUrl,
  projectKeys: prevParams.projectKeys,
  commitMessages: prevParams.commitMessages,
  sprintId: sprint.id,
  sprintName: sprint.name,
  sprintState: sprint.state,
  sprintStartDate: sprint.startDate || null,
  sprintEndDate: sprint.endDate || null
} }];

// 첫 페이지 조회를 위한 초기 파라미터 설정
const data = $input.first().json;
return [{ json: {
  boardId: data.boardId,
  baseUrl: data.baseUrl,
  projectKeys: data.projectKeys,
  commitMessages: data.commitMessages,
  sprintId: data.sprintId,
  sprintName: data.sprintName,
  sprintState: data.sprintState,
  sprintStartDate: data.sprintStartDate,
  sprintEndDate: data.sprintEndDate,
  startAt: 0,
  maxResults: 100,
  allIssues: []
} }];

const pageData = $input.first().json;
const loopState = $('Pagination Loop').first().json;

const issues = pageData.issues || [];
const total = pageData.total || 0;
const nextStart = loopState.startAt + issues.length;

// 누적 이슈 합산
const accumulated = (loopState.allIssues || []).concat(
  issues.map(issue => ({
    key: issue.key,
    summary: issue.fields?.summary || '',
    status: issue.fields?.status?.name || 'Unknown',
    statusCategory: issue.fields?.status?.statusCategory?.name || 'Unknown',
    storyPoints: issue.fields?.customfield_10016 || issue.fields?.story_points || null,
    issueType: issue.fields?.issuetype?.name || 'Task',
    assignee: issue.fields?.assignee?.displayName || null
  }))
);

const hasMore = nextStart < total && issues.length > 0;

return [{ json: {
  boardId: loopState.boardId,
  baseUrl: loopState.baseUrl,
  projectKeys: loopState.projectKeys,
  commitMessages: loopState.commitMessages,
  sprintId: loopState.sprintId,
  sprintName: loopState.sprintName,
  sprintState: loopState.sprintState,
  sprintStartDate: loopState.sprintStartDate,
  sprintEndDate: loopState.sprintEndDate,
  startAt: nextStart,
  maxResults: loopState.maxResults,
  allIssues: accumulated,
  total,
  hasMore
} }];

const data = $input.first().json;
const issues = data.allIssues || [];

const statusMap = { todo: 0, in_progress: 0, in_review: 0, done: 0, other: 0 };
const doneTitles = new Set();
const inProgressTitles = new Set();

for (const issue of issues) {
  const s = (issue.status || '').toLowerCase().trim();
  const cat = (issue.statusCategory || '').toLowerCase().trim();

  const isDone = cat === 'done' || cat === '완료'
    || s === 'done' || s === '완료' || s === 'closed' || s === 'resolved';
  const isReview = s.includes('review') || s.includes('pr') || s.includes('testing') || s.includes('qa');
  const isInProgress = cat === 'indeterminate' || cat === '진행 중'
    || s === 'in progress' || s === '진행 중'
    || s.includes('progress') || s.includes('doing') || s.includes('dev') || s.includes('wip');
  const isTodo = cat === 'new' || cat === '해야 할 일'
    || s === 'to do' || s === 'todo' || s === '해야 할 일' || s === 'open' || s === 'backlog';

  if (isDone) {
    statusMap.done++;
    doneTitles.add(issue.key + ' ' + issue.summary.substring(0, 40));
  } else if (isReview) {
    statusMap.in_review++;
    inProgressTitles.add(issue.key + ' ' + issue.summary.substring(0, 40));
  } else if (isInProgress) {
    statusMap.in_progress++;
    inProgressTitles.add(issue.key + ' ' + issue.summary.substring(0, 40));
  } else if (isTodo) {
    statusMap.todo++;
  } else {
    statusMap.other++;
  }
}

const allSP = issues.map(i => i.storyPoints).filter(sp => sp !== null && sp !== undefined);
const spTotal = allSP.reduce((acc, sp) => acc + (Number(sp) || 0), 0);
const doneSP = issues
  .filter(i => {
    const s = (i.status || '').toLowerCase().trim();
    const cat = (i.statusCategory || '').toLowerCase().trim();
    return cat === 'done' || cat === '완료' || s === 'done' || s === '완료' || s === 'closed' || s === 'resolved';
  })
  .reduce((acc, i) => acc + (Number(i.storyPoints) || 0), 0);

const spBurnedRate = spTotal > 0 ? Math.round((doneSP / spTotal) * 100) : 0;
const ticketDoneRate = issues.length > 0 ? Math.round((statusMap.done / issues.length) * 100) : 0;

return [{ json: {
  boardId: data.boardId,
  baseUrl: data.baseUrl,
  commitMessages: data.commitMessages,
  sprintId: data.sprintId,
  sprintName: data.sprintName,
  sprintStartDate: data.sprintStartDate,
  sprintEndDate: data.sprintEndDate,
  total_tickets: issues.length,
  done: statusMap.done,
  in_review: statusMap.in_review,
  in_progress: statusMap.in_progress,
  todo: statusMap.todo,
  other: statusMap.other,
  sp_total: spTotal,
  sp_burned: doneSP,
  sp_burned_rate: spBurnedRate,
  ticket_done_rate: ticketDoneRate,
  done_tickets: Array.from(doneTitles).slice(0, 20),
  incomplete_tickets: Array.from(inProgressTitles).slice(0, 20),
  allIssues: issues
} }];

const data = $input.first().json;
const commitMessages = data.commitMessages || [];
const issues = data.allIssues || [];

// Commit 메시지에서 Jira 이슈 키 추출 ([WBS-123] 또는 WBS-123 패턴)
const jiraKeyPattern = /\b([A-Z][A-Z0-9]+-\d+)\b/g;

const commitJiraMap = {};
for (const msg of commitMessages) {
  const matches = [...msg.matchAll(jiraKeyPattern)].map(m => m[1]);
  for (const key of matches) {
    if (!commitJiraMap[key]) commitJiraMap[key] = [];
    commitJiraMap[key].push(msg.substring(0, 80));
  }
}

// 연결된 티켓 vs 미연결 티켓 분류
const issueKeys = new Set(issues.map(i => i.key));
const linkedKeys = Object.keys(commitJiraMap).filter(k => issueKeys.has(k));
const orphanCommitKeys = Object.keys(commitJiraMap).filter(k => !issueKeys.has(k));
const noCommitIssues = issues
  .filter(i => !commitJiraMap[i.key] && (i.statusCategory?.toLowerCase() !== 'done') && (i.status?.toLowerCase() !== 'done'))
  .map(i => i.key)
  .slice(0, 20);

return [{ json: {
  sprintId: data.sprintId,
  sprintName: data.sprintName,
  sprintStartDate: data.sprintStartDate,
  sprintEndDate: data.sprintEndDate,
  total_tickets: data.total_tickets,
  done: data.done,
  in_review: data.in_review,
  in_progress: data.in_progress,
  todo: data.todo,
  sp_total: data.sp_total,
  sp_burned: data.sp_burned,
  sp_burned_rate: data.sp_burned_rate,
  ticket_done_rate: data.ticket_done_rate,
  done_tickets: data.done_tickets,
  incomplete_tickets: data.incomplete_tickets,
  jira_commit_map: commitJiraMap,
  linked_ticket_count: linkedKeys.length,
  orphan_commit_keys: orphanCommitKeys,
  no_commit_issues: noCommitIssues
} }];
